class Parser {
  parse() {
    return "base";
  }
}

class JsonParser extends Parser {
  parse = () => "json";
}

class StrictJsonParser extends JsonParser {
  parse() {
    return "strict";
  }
  fallback() {
    return super.parse();
  }
}

const p = new StrictJsonParser();
console.log(p.parse());
console.log(p.fallback());
